#include <stdio.h>
#include "throttle_feedback_pairs_cases.h"
#include "guidance_length_phased.h"
static void emit(throttle_feedback_pairs_case *c,uint16_t n,uint16_t stage,unsigned result){uint16_t w[TFP_WORDS],head[3]={n,stage,(uint16_t)result};tfp_words(c,w);if(fwrite(head,sizeof head,1,stdout)!=1||fwrite(w,sizeof w,1,stdout)!=1)fprintf(stderr,"write failure\n");}
int main(void){uint16_t k;for(k=0;k<TF_CASES;++k){throttle_feedback_pairs_case c;throttle_feedback_case *x=&c.source;p66_preparation *s=&x->previous.base.previous.previous.previous.preparation;p66_scale_scratch *sc=&x->previous.base.previous.previous.previous.scratch;p66_elapsed_state *el=&x->previous.base.previous.elapsed;p66_divide_scratch *d=&x->previous.base.scratch;p66_norm_scratch *n=&x->previous.norm;p66_pushdown *p=&x->previous.base.previous.previous.push;unsigned result;tfp_input(&c,k);if(tfp_apply(&c))return 2;emit(&c,k,209,0);result=(unsigned)p66_length_square_phase(s,sc,el,d,n,p);if(result)return 2;c.control.pc=03202;c.control.q=0140;c.control.fb=0;c.control.eb=03400;c.control.bb=7;c.control.loc=03437;c.control.cyr=040005;c.control.edop=0052;c.control.next_pair=255;emit(&c,k,210,0);result=(unsigned)p66_length_root_phase(s,sc,el,d,n,p);if(result)return 2;c.control.pc=03210;c.control.q=3;emit(&c,k,211,0);result=(unsigned)p66_length_finish_phase(s,sc,el,d,n,p);if(result)return 2;c.control.pc=06061;emit(&c,k,212,0);result=(unsigned)p66_feedback_timestamp_after_length(s,n,p,&c.control);if(result)return 2;emit(&c,k,213,0);}return 0;}
